using System;

namespace UI_Desktop.Store;

internal static class StoreSupportChatHtmlBuilder
{
	internal static string BuildDocument(Guid readyId)
	{
		return "<!DOCTYPE html>\n<html lang=\"vi\">\n<head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Chat hỗ trợ</title>\n    <style>\n        :root {\n            color-scheme: dark;\n            font-family: \"Segoe UI\", Arial, sans-serif;\n            background: #071018;\n            color: #eaf4ff;\n        }\n        * { box-sizing: border-box; }\n        html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; }\n        body { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; border: 1px solid rgba(102, 192, 244, .34); background: linear-gradient(180deg, #0c1926, #071018); }\n        button, textarea { font: inherit; }\n        button { cursor: pointer; touch-action: manipulation; }\n        button:focus-visible, textarea:focus-visible { outline: 2px solid #66c0f4; outline-offset: 2px; }\n        header { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 69px; padding: 12px 14px; border-bottom: 1px solid rgba(102, 192, 244, .18); background: rgba(20, 35, 51, .48); }\n        header strong { display: block; color: #f4fbff; font-size: 17px; line-height: 1.3; }\n        header span { display: block; margin-top: 4px; color: #a8bed1; font-size: 12px; line-height: 1.35; overflow-wrap: anywhere; }\n        header span.is-error { color: #fecaca; }\n        .close { flex: none; width: 44px; height: 44px; border: 1px solid rgba(255,255,255,.16); border-radius: 6px; background: rgba(255,255,255,.06); color: #eaf4ff; font-size: 22px; line-height: 1; }\n        .close:hover { background: #9b3030; }\n        .messages { display: flex; flex-direction: column; gap: 10px; min-height: 0; overflow-y: auto; padding: 14px; scrollbar-color: #536a79 #101e2b; scrollbar-width: thin; }\n        .empty { margin: auto; color: #b1c5d6; text-align: center; font-size: 13px; line-height: 1.5; }\n        .empty[hidden] { display: none; }\n        .message { max-width: 86%; min-width: 0; padding: 10px 11px; border: 1px solid rgba(116,147,181,.30); border-radius: 8px; background: rgba(18,31,46,.96); color: #eaf4ff; }\n        .message.is-user { align-self: flex-end; border-color: rgba(45,212,191,.43); background: rgba(17,94,89,.40); }\n        .message.is-admin { align-self: flex-start; }\n        .message.is-pending { opacity: .76; }\n        .message.is-error { border-color: rgba(248,113,113,.70); background: rgba(127,29,29,.36); }\n        .meta { display: flex; justify-content: space-between; gap: 10px; min-width: 0; margin-bottom: 6px; color: #b5c7d6; font-size: 11px; font-weight: 700; line-height: 1.4; }\n        .meta span:first-child { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n        .meta span:last-child { flex: none; }\n        .body { white-space: pre-wrap; overflow-wrap: anywhere; font-size: 13px; line-height: 1.5; }\n        .state { margin-top: 6px; color: #fecaca; font-size: 11px; line-height: 1.4; }\n        .retry { min-height: 32px; margin-top: 8px; padding: 5px 10px; border: 1px solid rgba(255,255,255,.23); border-radius: 5px; background: rgba(255,255,255,.10); color: #f8fafc; font-size: 11px; font-weight: 700; }\n        form { display: grid; grid-template-columns: minmax(0, 1fr) 74px; align-items: end; gap: 10px; padding: 12px; border-top: 1px solid rgba(102,192,244,.18); background: #0c1722; }\n        textarea { display: block; width: 100%; height: 64px; min-height: 64px; resize: none; overflow-y: auto; padding: 10px; border: 1px solid rgba(116,147,181,.42); border-radius: 4px; background: #071018; color: #f8fafc; font-size: 13px; line-height: 1.4; }\n        textarea::placeholder { color: #a0b5c8; }\n        .send { height: 64px; align-self: end; border: 0; border-radius: 7px; background: linear-gradient(135deg, #0e95cc, #0fa89b); color: white; font-size: 14px; font-weight: 800; }\n        .send:hover { filter: brightness(1.12); }\n        @media (max-height: 410px) { header { min-height: 58px; } textarea, .send { height: 48px; min-height: 48px; } }\n        @media (prefers-reduced-motion: reduce) { * { scroll-behavior: auto !important; } }\n    </style>\n</head>\n<body>\n    <header>\n        <div><strong>Chat hỗ trợ</strong><span id=\"status\" role=\"status\" aria-live=\"polite\">Sẵn sàng kết nối</span></div>\n        <button class=\"close\" type=\"button\" id=\"close\" aria-label=\"Đóng chat hỗ trợ\">×</button>\n    </header>\n    <main class=\"messages\" id=\"messages\" aria-label=\"Tin nhắn chat hỗ trợ\">\n        <div class=\"empty\" id=\"empty\">Mở kết nối hỗ trợ để bắt đầu trò chuyện.</div>\n    </main>\n    <form id=\"composer\">\n        <textarea id=\"input\" aria-label=\"Nội dung tin nhắn\" maxlength=\"4000\" rows=\"2\" placeholder=\"Nhập tin nhắn...\"></textarea>\n        <button class=\"send\" type=\"submit\">Gửi</button>\n    </form>\n    <script>\n        const messages = document.getElementById('messages');\n        const empty = document.getElementById('empty');\n        const status = document.getElementById('status');\n        const input = document.getElementById('input');\n        const post = value => window.chrome?.webview?.postMessage(value);\n        let conversationId = '';\n        const statusMap = {\n            open: 'Đang mở', pending_user: 'Đang chờ bạn phản hồi',\n            pending_admin: 'Đang chờ admin phản hồi', resolved: 'Đã xử lý', closed: 'Đã đóng'\n        };\n        function setStatus(text, isError = false) {\n            status.textContent = statusMap[String(text || '').toLowerCase()] || text || 'Đang trực tuyến';\n            status.classList.toggle('is-error', !!isError);\n        }\n        function scrollBottom() { messages.scrollTop = messages.scrollHeight; }\n        function timeText(value) {\n            const date = value ? new Date(value) : null;\n            return date && !Number.isNaN(date.getTime())\n                ? new Intl.DateTimeFormat('vi-VN', { hour: '2-digit', minute: '2-digit' }).format(date) : '';\n        }\n        function id() {\n            return window.crypto?.randomUUID?.() || 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {\n                const n = Math.random() * 16 | 0;\n                return (c === 'x' ? n : (n & 3 | 8)).toString(16);\n            });\n        }\n        function findClient(clientId) {\n            return clientId ? Array.from(messages.querySelectorAll('[data-client-id]'))\n                .find(node => node.dataset.clientId === clientId) : null;\n        }\n        function render(message, options = {}) {\n            if (!message || message.isInternal || message.isDeleted) return null;\n            const messageId = message.messageId || '';\n            const clientId = message.clientMessageId || options.clientId || '';\n            if (messageId && Array.from(messages.querySelectorAll('[data-message-id]'))\n                .some(node => node.dataset.messageId === messageId)) return null;\n            const old = findClient(clientId);\n            const node = old && old.classList.contains('is-pending') ? old : document.createElement('article');\n            node.className = 'message';\n            const isAdmin = (message.senderRole || options.role) === 'admin';\n            node.classList.add(isAdmin ? 'is-admin' : 'is-user');\n            if (options.pending) node.classList.add('is-pending');\n            if (options.error) node.classList.add('is-error');\n            if (messageId) node.dataset.messageId = messageId;\n            if (clientId) node.dataset.clientId = clientId;\n            node.textContent = '';\n            const meta = document.createElement('div'); meta.className = 'meta';\n            const sender = document.createElement('span');\n            sender.textContent = message.senderDisplayName || (isAdmin ? 'Hỗ trợ' : 'Bạn');\n            const at = document.createElement('span');\n            at.textContent = options.pending ? 'Đang gửi' : timeText(message.createdAt);\n            meta.append(sender, at);\n            const body = document.createElement('div'); body.className = 'body';\n            body.textContent = message.body || '';\n            node.append(meta, body);\n            if (options.pending || options.error) {\n                const state = document.createElement('div'); state.className = 'state';\n                state.textContent = options.error ? options.error : 'Đang gửi...';\n                node.append(state);\n            }\n            if (!old || old !== node) messages.append(node);\n            empty.hidden = true;\n            scrollBottom();\n            return node;\n        }\n        function load(detail) {\n            const nextId = detail?.conversation?.conversationId || '';\n            const retained = !conversationId || conversationId === nextId\n                ? Array.from(messages.querySelectorAll('.is-pending, .is-error')) : [];\n            conversationId = nextId;\n            messages.replaceChildren(empty);\n            empty.hidden = false;\n            const history = Array.isArray(detail?.messages) ? detail.messages : [];\n            history.forEach(message => render(message));\n            retained.forEach(node => {\n                if (!findClient(node.dataset.clientId || '')) messages.append(node);\n            });\n            empty.hidden = messages.children.length > 1;\n            setStatus(detail?.conversation?.statusText);\n            scrollBottom();\n        }\n        function receiveMessage(payload) {\n            if (payload?.conversation) updateConversation(payload.conversation);\n            render(payload?.message);\n        }\n        function updateConversation(conversation) {\n            if (conversation?.conversationId) conversationId = conversation.conversationId;\n            if (conversation?.statusText) setStatus(conversation.statusText);\n        }\n        function confirmMessage(clientId, result) {\n            const old = findClient(clientId);\n            if (old && !old.dataset.messageId) old.remove();\n            if (result?.supportMessage) render(result.supportMessage);\n            setStatus('Đã gửi');\n        }\n        function failMessage(clientId, error) {\n            const node = findClient(clientId);\n            if (node) {\n                node.classList.remove('is-pending');\n                node.classList.add('is-error');\n                const state = node.querySelector('.state') || document.createElement('div');\n                state.className = 'state'; state.textContent = error || 'Gửi lỗi';\n                if (!state.parentElement) node.append(state);\n                let retry = node.querySelector('.retry');\n                if (!retry) {\n                    retry = document.createElement('button'); retry.className = 'retry';\n                    retry.type = 'button'; retry.textContent = 'Thử lại'; node.append(retry);\n                }\n                retry.onclick = () => {\n                    node.classList.remove('is-error'); node.classList.add('is-pending');\n                    state.textContent = 'Đang gửi...'; retry.remove();\n                    post({ type: 'sendSupportMessage', body: node.querySelector('.body')?.textContent || '', clientMessageId: clientId });\n                };\n            }\n            setStatus(error || 'Không thể gửi tin nhắn', true);\n        }\n        function clear() { conversationId = ''; messages.replaceChildren(empty); empty.hidden = false; input.value = ''; setStatus('Sẵn sàng kết nối'); }\n        window.__nestgSupport = { load, receiveMessage, updateConversation, confirmMessage, failMessage, setStatus, clear, focus: () => input.focus() };\n        document.getElementById('close').addEventListener('click', () => post({ type: 'closeSupportChat' }));\n        document.addEventListener('keydown', event => {\n            if (event.key === 'Escape') { event.preventDefault(); post({ type: 'closeSupportChat' }); }\n        });\n        input.addEventListener('keydown', event => {\n            if (event.key === 'Enter' && !event.shiftKey) {\n                event.preventDefault(); document.getElementById('composer').requestSubmit();\n            }\n        });\n        document.getElementById('composer').addEventListener('submit', event => {\n            event.preventDefault();\n            const body = input.value.trim();\n            if (!body) { setStatus('Nhập nội dung trước khi gửi.', true); input.focus(); return; }\n            const clientId = id();\n            render({ body, senderRole: 'customer' }, { pending: true, clientId });\n            input.value = '';\n            post({ type: 'sendSupportMessage', body, clientMessageId: clientId });\n        });\n        post({ type: 'supportChatReady', readyId: '__CHAT_READY_ID__' });\n    </script>\n</body>\n</html>".Replace("__CHAT_READY_ID__", readyId.ToString("D"), StringComparison.Ordinal);
	}
}
